WITH cleaned AS (SELECT *, COALESCE(pressure, 0) AS pressure_filled FROM device_readings WHERE reading_ts >= DATE '2025-09-01' AND status_bits <= 4), gaps AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL 15 MINUTES THEN 1 ELSE 0 END AS session_start_flag FROM cleaned), sessions_device_readings AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps) SELECT CASE WHEN humidity >= 76 THEN 'LARGE' ELSE 'SMALL' END AS humidity_tier, device_code, DATE_TRUNC('HOUR', reading_ts) AS hour_window, MAX(reading_ts) AS last_reading_ts, PERCENTILE_APPROX(session_start_flag, 0.95) AS session_start_flag_p95, GROUPING(CASE WHEN humidity >= 76 THEN 'LARGE' ELSE 'SMALL' END) AS gid FROM sessions_device_readings GROUP BY GROUPING SETS ((CASE WHEN humidity >= 76 THEN 'LARGE' ELSE 'SMALL' END, device_code, DATE_TRUNC('HOUR', reading_ts)), (CASE WHEN humidity >= 76 THEN 'LARGE' ELSE 'SMALL' END, device_code), ()) HAVING session_start_flag_p95 < 0 ORDER BY session_start_flag_p95 DESC
